fc34545f62"},{"url":"https://www.bibliotheek.nl/catalogus/titel.434916706.html/maia-s-verhaal/","role":"independent exact-edition and/or content identity corroboration"},{"url":"https://metadata.isbn.nl/ie_fcache/0000541899_De_zeven_zussen_0_0.jpg","role":"exact-edition image from its own edition block; visually checked","sha256":"200071b6417ac3da1b6e6adf443f2b4b08127f125243585c60d1f1debcee8ce0","bytes":834318}],"review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"hebban-priority-20261031"},"origin":"https://metadata.isbn.nl/984567/de-zeven-zussen.html"},{"relation":"catalog_work_descriptions","key":{"work_id":1936,"language":"nl"},"before":null,"after":{"work_id":1936,"language":"nl","bound_author_id":849,"text":"Daniel Sempere bezoekt met zijn vader een verborgen boekenbewaarplaats in Barcelona. Daar kiest hij een roman van Julián Carax die hem niet meer loslaat. Zijn nieuwsgierigheid naar de schrijver brengt hem in contact met mensen wier levens met het boek verweven raken. Terwijl de schaduw van het Franco-regime over de stad ligt, ontdekt Daniel dat het verleden niet afgesloten is. Zijn zoektocht naar een auteur verandert zo ook zijn eigen leven.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/97850/de-schaduw-van-de-wind.html","evidence":[{"url":"https://metadata.isbn.nl/97850/de-schaduw-van-de-wind.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"hebban-priority-20261031"},"origin":"https://metadata.isbn.nl/97850/de-schaduw-van-de-wind.html"},{"relation":"catalog_work_descriptions","key":{"work_id":9530,"language":"nl"},"before":null,"after":{"work_id":9530,"language":"nl","bound_author_id":5454,"text":"Een voormalig Amerikaans spion probeert zijn oude bestaan achter zich te laten. Een moord in een hotel in Manhattan brengt hem echter opnieuw in beweging: de dader lijkt gebruik te hebben gemaakt van kennis uit zijn eigen boek over forensisch onderzoek. Het onderzoek groeit uit tot een jacht op een onbekende tegenstander. Onder de codenaam Pelgrim moet hij achterhalen welke dreiging achter de afzonderlijke aanwijzingen schuilgaat en hoe die kan worden gestopt.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/433510/ik-ben-pelgrim.html","evidence":[{"url":"https://metadata.isbn.nl/433510/ik-ben-pelgrim.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"hebban-priority-20261031"},"origin":"https://metadata.isbn.nl/433510/ik-ben-pelgrim.html"},{"relation":"catalog_work_descriptions","key":{"work_id":93,"language":"nl"},"before":null,"after":{"work_id":93,"language":"nl","bound_author_id":80,"text":"Een bijzondere treinreis brengt Harry Potter naar Zweinstein, een school waar magie deel uitmaakt van het dagelijks leven. Hij krijgt lessen in toverdranken, leert over bezemstelen en ontmoet een wereld vol wonderlijke mogelijkheden en gevaren. Zijn kennismaking met die wereld blijft niet bij schoolwerk alleen. Achter de vertrouwde omgeving van de school dreigt de invloed van Voldemort. Dit eerste deel volgt Harry terwijl hij zijn plaats vindt tussen nieuwe ervaringen en een gevaarlijke tegenstander.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/122485/harry-potter-en-de-steen-der-wijzen.html","evidence":[{"url":"https://metadata.isbn.nl/122485/harry-potter-en-de-steen-der-wijzen.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"hebban-priority-20261031"},"origin":"https://metadata.isbn.nl/122485/harry-potter-en-de-steen-der-wijzen.html"},{"relation":"catalog_work_descriptions","key":{"work_id":1006,"language":"nl"},"before":null,"after":{"work_id":1006,"language":"nl","bound_author_id":636,"text":"Twee engelen kijken terug op gebeurtenissen die zij met een bepaald doel hebben beïnvloed. Menselijke relaties en keuzes blijken deel van een groter plan waarin geschiedenis, erfelijkheid en religie samenkomen. Tegelijk stelt de roman vragen over de verhouding tussen de hemel en een mensheid die steeds meer technisch kan verklaren en beheersen. Harry Mulisch verbindt deze verschillende perspectieven in een verhaal waarin vriendschap en morele vragen een belangrijke plaats innemen.","source_type":"official_publisher","source_name":"De Bezige Bij","source_url":"https://www.debezigebij.nl/boek/de-ontdekking-van-de-hemel/","evidence":[{"url":"https://www.debezigebij.nl/boek/de-ontdekking-van-de-hemel/","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof"},{"url":"https://www.bibliotheek.nl/catalogus/titel.441307329.html/de-ontdekking-van-de-hemel/","role":"Content/identity corroboration"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"hebban-priority-20261031"},"origin":"https://www.debezigebij.nl/boek/de-ontdekking-van-de-hemel/"},{"relation":"catalog_work_descriptions","key":{"work_id":1440,"language":"nl"},"before":null,"after":{"work_id":1440,"language":"nl","bound_author_id":761,"text":"In het Parijs van 1942 wordt de jonge Sarah met haar ouders opgepakt tijdens een razzia. Haar broertje blijft verborgen achter in hun woning. Zestig jaar later onderzoekt journaliste Julia Jarmond wat er tijdens die gebeurtenissen is gebeurd. In archieven ontdekt zij verbanden die veel dichter bij haar eigen familie komen dan zij verwachtte. De twee verhaallijnen laten zien hoe een gewelddadig verleden blijft doorwerken in het leven van latere generaties.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/69636/haar-naam-was-sarah.html","evidence":[{"url":"https://metadata.isbn.nl/69636/haar-naam-was-sarah.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"hebban-priority-20261031"},"origin":"https://metadata.isbn.nl/69636/haar-naam-was-sarah.html"},{"relation":"catalog_work_descriptions","key":{"work_id":1435,"language":"nl"},"before":null,"after":{"work_id":1435,"language":"nl","bound_author_id":758,"text":"Na de dood van hun adoptievader verzamelen Maia en haar zussen zich bij hun ouderlijk huis aan het Meer van Genève. Een brief geeft Maia een eerste aanwijzing over haar afkomst. Haar onderzoek voert haar naar Rio de Janeiro en naar gebeurtenissen die tientallen jaren eerder ook met Parijs verbonden waren. Terwijl zij de sporen van haar familie volgt, zoekt Maia uit wat die geschiedenis voor haar eigen identiteit betekent. Dit is het eerste deel van de reeks.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/984567/de-zeven-zussen.html","evidence":[{"url":"https://metadata.isbn.nl/984567/de-zeven-zussen.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"hebban-priority-20261031"},"origin":"https://metadata.isbn.nl/984567/de-zeven-zussen.html"}],"bindings":[{"work":{"id":1936,"title":"De Schaduw van de Wind","cover_id":null,"subjects":null,"subtitle":null,"author_id":849,"work_type":null,"created_at":"2026-09-16T17:01:58.791761+00:00","source_type":"open_library","open_library_id":"OL34874211W","first_publish_year":2008,"native_identity_key":null},"author":{"id":849,"name":"Carlos Ruiz Zafón","created_at":"2026-09-16T15:13:29.394602+00:00","open_library_id":"OL2632116A"}},{"work":{"id":9530,"title":"I am Pilgrim","cover_id":null,"subjects":null,"subtitle":null,"author_id":5454,"work_type":null,"created_at":"2026-10-03T17:13:22.654831+00:00","source_type":null,"open_library_id":"OL17354744W","first_publish_year":2013,"native_identity_key":null},"author":{"id":5454,"name":"Terry Hayes","created_at":"2026-10-03T17:13:22.654831+00:00","open_library_id":"OL1556669A"}},{"work":{"id":93,"title":"Harry Potter and the Philosopher''s Stone","cover_id":null,"subjects":null,"subtitle":null,"author_id":80,"work_type":null,"created_at":"2026-09-01T15:21:01.726345+00:00","source_type":"open_library","open_library_id":"OL82563W","first_publish_year":1997,"native_identity_key":null},"author":{"id":80,"name":"J. K. Rowling","created_at":"2026-09-01T15:21:01.522441+00:00","open_library_id":"OL23919A"}},{"work":{"id":1006,"title":"De ontdekking van de hemel","cover_id":null,"subjects":null,"subtitle":null,"author_id":636,"work_type":null,"created_at":"2026-09-03T19:06:04.363575+00:00","source_type":"open_library","open_library_id":"OL659062W","first_publish_year":1993,"native_identity_key":null},"author":{"id":636,"name":"Harry Mulisch","created_at":"2026-09-03T19:06:04.078917+00:00","open_library_id":"OL51237A"}},{"work":{"id":1440,"title":"Haar naam was Sarah / druk 59","cover_id":null,"subjects":null,"subtitle":null,"author_id":761,"work_type":null,"created_at":"2026-09-16T15:08:41.595464+00:00","source_type":"open_library","open_library_id":"OL29271146W","first_publish_year":2010,"native_identity_key":null},"author":{"id":761,"name":"Tatiana de Rosnay","created_at":"2026-09-16T15:08:41.243959+00:00","open_library_id":"OL9123208A"}},{"work":{"id":1435,"title":"De zeven zussen","cover_id":null,"subjects":null,"subtitle":null,"author_id":758,"work_type":null,"created_at":"2026-09-16T15:08:29.849994+00:00","source_type":"open_library","open_library_id":"OL34536006W","first_publish_year":2018,"native_identity_key":null},"author":{"id":758,"name":"Lucinda Riley","created_at":"2026-09-16T15:08:29.626589+00:00","open_library_id":"OL7758106A"}}],"authorCorpora":[]}'::jsonb;a jsonb;b jsonb;actual jsonb;oldrow jsonb;nextrow jsonb;k jsonb;kv record;ids jsonb:='{}';cols text;vals text;v_id bigint;i integer:=0;n integer;begin
 for b in select value from jsonb_array_elements(payload->'bindings') loop
  select to_jsonb(w) into actual from public.works w where id=(b->'work'->>'id')::bigint;
  if actual is distinct from b->'work' and not exists(select 1 from jsonb_array_elements(payload->'actions') p where p->>'relation'='works' and p->'key'=jsonb_build_object('id',(b->'work'->>'id')::bigint) and actual=p->'after') then raise exception 'Work preflight drift';end if;
  select to_jsonb(t) into actual from public.authors t where id=(b->'author'->>'id')::bigint;
  if actual is distinct from b->'author' then raise exception 'Author preflight drift';end if;
 end loop;
 for b in select value from jsonb_array_elements(payload->'authorCorpora') loop
  select coalesce(jsonb_agg(to_jsonb(w) order by id),'[]') into actual from public.works w where author_id=(b->>'author_id')::bigint and not exists(select 1 from jsonb_array_elements(payload->'actions') p where p->>'relation'='works' and p->'before'='null' and w.native_identity_key=p->'after'->>'native_identity_key');
  select coalesce(jsonb_agg(to_jsonb(jsonb_populate_record(null::public.works,value)) order by (value->>'id')::bigint),'[]') into oldrow from jsonb_array_elements(b->'rows');
  select coalesce(jsonb_agg(to_jsonb(jsonb_populate_record(null::public.works,coalesce((select p->'after' from jsonb_array_elements(payload->'actions') p where p->>'relation'='works' and p->'before'<>'null' and p->'key'=jsonb_build_object('id',(v.value->>'id')::bigint)),v.value))) order by (v.value->>'id')::bigint),'[]') into nextrow from jsonb_array_elements(b->'rows') v;
  if actual is distinct from oldrow and actual is distinct from nextrow then raise exception 'New Work author corpus drift; repeat identity review';end if;
 end loop;
 for a in select value from jsonb_array_elements(payload->'actions') loop
  i:=i+1;k:=a->'key';nextrow:=a->'after';oldrow:=a->'before';
  if a->>'relation' not in ('authors','works','editions','catalog_work_descriptions','catalog_edition_metadata') then raise exception 'Unreviewed relation';end if;
  for kv in select * from jsonb_each(nextrow) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then
    if not ids ? substring(kv.value#>>'{}',2) then raise exception 'Unresolved parent reference';end if;
    nextrow:=jsonb_set(nextrow,array[kv.key],ids->substring(kv.value#>>'{}',2));
   end if;
  end loop;
  for kv in select * from jsonb_each(k) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then k:=jsonb_set(k,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;
  end loop;
  execute format('select to_jsonb(t) from public.%I t where to_jsonb(t) @> $1 for update',a->>'relation') into actual using k;
  if oldrow<>'null'::jsonb then
   execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into oldrow using oldrow;
   execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into nextrow using nextrow;
   if actual is not distinct from nextrow then continue;end if;
   if actual is distinct from oldrow then raise exception 'Changed existing row in % at action %',a->>'relation',i;end if;
   select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,a->>'relation',key),',') into cols from jsonb_each(nextrow) where value is distinct from oldrow->key;
   execute format('update public.%I t set %s where to_jsonb(t) @> $2 returning to_jsonb(t)',a->>'relation',cols) into actual using nextrow,k;
   insert into catalog_release_receipt values(i,a->>'relation',k,oldrow,actual);
  elsif actual is not null then
   if a->>'relation' in ('catalog_work_descriptions','catalog_edition_metadata') then
    execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into nextrow using nextrow;
    if actual is distinct from nextrow then raise exception 'Existing reviewed presentation differs; never overwrite';end if;
   elsif not actual @> nextrow then raise exception 'Existing natural identity differs';end if;
  else
   if a->>'relation'='editions' and exists(select 1 from public.editions e where (nextrow->>'isbn_13' is not null and regexp_replace(coalesce(e.isbn_13,''),'[-[:space:]]','','g')=nextrow->>'isbn_13') or (nextrow->>'isbn_10' is not null and upper(regexp_replace(coalesce(e.isbn_10,''),'[-[:space:]]','','g'))=nextrow->>'isbn_10') or (nextrow->>'open_library_edition_id' is not null and e.open_library_edition_id=nextrow->>'open_library_edition_id')) then raise exception 'Global edition identity collision';end if;
   select string_agg(format('%I',key),',' order by key),string_agg(format('(jsonb_populate_record(null::public.%I,$1)).%I',a->>'relation',key),',' order by key) into cols,vals from jsonb_each(nextrow);
   execute format('insert into public.%I(%s) select %s returning to_jsonb(%I)',a->>'relation',cols,vals,a->>'relation') into actual using nextrow;
   insert into catalog_release_receipt values(i,a->>'relation',k,null,actual);
  end if;
  if actual ? 'id' then ids:=jsonb_set(ids,array[a->>'ref'],actual->'id');end if;
 end loop;
 select count(*) into n from catalog_release_receipt;
 if n not in (0,17) then raise exception 'Partial install/replay; expected zero or all actions, got %',n;end if;
end;$release$;
